use std::collections::HashMap;

use flutter_rust_bridge::frb;
use serde::{Deserialize, Serialize};

use crate::models::video_detail::BackendVideoDetail;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[frb(json_serializable)]
pub struct Episode {
    pub label: String,
    pub url: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[frb(json_serializable)]
pub struct PlaySource {
    pub name: String,
    pub parse_api: String,
    pub episodes: Vec<Episode>,
    pub need_resolve: bool,
    pub headers: HashMap<String, String>,
}

fn parse_episodes(raw: &str, _is_direct: bool) -> Vec<Episode> {
    raw.split('#')
        .filter_map(|part| {
            let (label, value) = part.split_once('$')?;
            let label = label.trim();
            let value = value.trim();
            if label.is_empty() || value.is_empty() {
                return None;
            }
            Some(Episode {
                label: label.to_string(),
                url: value.to_string(),
            })
        })
        .collect()
}

fn parse_headers(raw: &str) -> HashMap<String, String> {
    raw.lines()
        .filter_map(|line| {
            let (name, value) = line.trim().split_once(':')?;
            let name = name.trim();
            let value = value.trim();
            if name.is_empty() || value.is_empty() {
                return None;
            }
            Some((name.to_string(), value.to_string()))
        })
        .collect()
}

pub fn parse_and_strip_play_sources(video_detail: BackendVideoDetail) -> Vec<PlaySource> {
    let Some(play_sources) = video_detail.vod_info.vod_url_with_player else {
        return Vec::new();
    };

    let mut video_sources = Vec::with_capacity(play_sources.len());
    for source in play_sources {
        let name = source.name;
        let raw_url = source.url;
        let parse_api = source.parse_api;
        let un_link_features = source.un_link_features;
        let is_direct = un_link_features == "m3u8";
        let headers = parse_headers(&source.headers);
        let episodes = parse_episodes(&raw_url, is_direct);
        let episode_count = episodes.len();

        video_sources.push(PlaySource {
            name,
            parse_api,
            episodes,
            need_resolve: !is_direct && episode_count > 0,
            headers,
        });
    }
    video_sources
}

